INSERT INTO `landing_pages` VALUES (1,'TGA Innovation Platform','[{\"data\": {\"items\": [{\"text\": {\"ar\": \"منصة الابتكار – تمكين مستقبل النقل من خلال التكنولوجيا والتعاون\", \"en\": \"Innovation Platform – Empowering the future of transport through technology and collaboration\"}, \"image\": {\"ar\": \"\", \"en\": \"\"}, \"title\": {\"ar\": \"الهيئة العامة للنقل\", \"en\": \"Transport General Authority\"}, \"main_action\": {\"url\": {\"ar\": \"/ar/programs\", \"en\": \"/en/programs\"}, \"title\": {\"ar\": \"استكشف البرامج\", \"en\": \"Explore Programs\"}}}, {\"text\": {\"ar\": \"بيئة خاضعة للرقابة تمكن المبتكرين من اختبار تقنيات النقل الجديدة ونماذج الأعمال تحت إشراف تنظيمي.\", \"en\": \"A controlled environment that enables innovators to test new transport technologies and business models under regulatory supervision.\"}, \"image\": {\"ar\": \"\", \"en\": \"\"}, \"title\": {\"ar\": \"البيئة التنظيمية التجريبية\", \"en\": \"Regulatory Sandbox\"}, \"main_action\": {\"url\": {\"ar\": \"/ar/programs\", \"en\": \"/en/programs\"}, \"title\": {\"ar\": \"قدم الآن\", \"en\": \"Apply Now\"}}}]}, \"type\": \"banner\"}, {\"data\": {\"list\": [{\"icon\": \"heroicon-o-rocket-launch\", \"title\": {\"ar\": \"البرامج المُطلقة\", \"en\": \"Programs Launched\"}, \"number\": \"5\"}, {\"icon\": \"heroicon-o-users\", \"title\": {\"ar\": \"المشاركون النشطون\", \"en\": \"Active Participants\"}, \"number\": \"250+\"}, {\"icon\": \"heroicon-o-document-text\", \"title\": {\"ar\": \"المشاريع المقدمة\", \"en\": \"Projects Submitted\"}, \"number\": \"120+\"}, {\"icon\": \"heroicon-o-building-office\", \"title\": {\"ar\": \"الشركاء\", \"en\": \"Partners\"}, \"number\": \"30+\"}], \"text\": {\"ar\": \"منصة الابتكار التابعة للهيئة العامة للنقل هي منظومة رقمية شاملة مصممة لتعزيز الابتكار في قطاع النقل. نربط رواد الأعمال والشركات الناشئة والشركات الراسخة بالدعم التنظيمي والموارد لتطوير حلول نقل متطورة للمملكة العربية السعودية.\", \"en\": \"The Transport General Authority Innovation Platform is a comprehensive digital ecosystem designed to foster innovation in the transport sector. We connect entrepreneurs, startups, and established companies with regulatory support and resources to develop cutting-edge transport solutions for the Kingdom of Saudi Arabia.\"}, \"title\": {\"ar\": \"عن منصة الابتكار\", \"en\": \"About the Innovation Platform\"}, \"main_action\": {\"url\": {\"ar\": \"/ar/about\", \"en\": \"/en/about\"}, \"title\": {\"ar\": \"اعرف المزيد\", \"en\": \"Learn More\"}}}, \"type\": \"about\"}, {\"data\": {\"text\": {\"ar\": \"استكشف الخدمات التي نقدمها لدعم الابتكار في قطاع النقل بالمملكة.\", \"en\": \"Explore the services we offer to support transport innovation in the Kingdom.\"}, \"title\": {\"ar\": \"خدماتنا\", \"en\": \"Our Services\"}, \"services\": [{\"icon\": \"heroicon-o-beaker\", \"tags\": {\"ar\": \"ابتكار، تنظيم، اختبار\", \"en\": \"Innovation, Regulation, Testing\"}, \"title\": {\"ar\": \"خدمة البيئة التنظيمية التجريبية\", \"en\": \"Regulatory Sandbox Service\"}, \"description\": {\"ar\": \"تقدم لاختبار حلول النقل المبتكرة في بيئة تنظيمية خاضعة للرقابة مع إشراف ودعم الهيئة العامة للنقل.\", \"en\": \"Apply to test your innovative transport solutions in a controlled regulatory environment with TGA oversight and support.\"}, \"main_action\": {\"url\": {\"ar\": \"/ar/services/1\", \"en\": \"/en/services/1\"}, \"title\": {\"ar\": \"تقديم\", \"en\": \"Apply\"}}, \"secondary_action\": {\"url\": {\"ar\": \"/ar/services/1\", \"en\": \"/en/services/1\"}, \"title\": {\"ar\": \"التفاصيل\", \"en\": \"Details\"}}}, {\"icon\": \"heroicon-o-truck\", \"tags\": {\"ar\": \"امتثال، تأجير سيارات، تنظيم\", \"en\": \"Compliance, Car Rental, Regulation\"}, \"title\": {\"ar\": \"خدمة الامتثال لتأجير السيارات\", \"en\": \"Car Rental Compliance Service\"}, \"description\": {\"ar\": \"تأكد من أن عمليات تأجير السيارات الخاصة بك تلبي جميع المتطلبات التنظيمية للهيئة العامة للنقل من خلال خدمة تقييم الامتثال والشهادات.\", \"en\": \"Ensure your car rental operations meet all TGA regulatory requirements through our compliance assessment and certification service.\"}, \"main_action\": {\"url\": {\"ar\": \"/ar/services/2\", \"en\": \"/en/services/2\"}, \"title\": {\"ar\": \"تقديم\", \"en\": \"Apply\"}}, \"secondary_action\": {\"url\": {\"ar\": \"/ar/services/2\", \"en\": \"/en/services/2\"}, \"title\": {\"ar\": \"التفاصيل\", \"en\": \"Details\"}}}]}, \"type\": \"services\"}, {\"data\": {\"logos\": [{\"image\": \"\", \"title\": {\"ar\": \"وزارة النقل\", \"en\": \"Ministry of Transport\"}}, {\"image\": \"\", \"title\": {\"ar\": \"صندوق التقنية السعودي\", \"en\": \"Saudi Technology Ventures\"}}, {\"image\": \"\", \"title\": {\"ar\": \"ابتكارات كاوست\", \"en\": \"KAUST Innovation\"}}, {\"image\": \"\", \"title\": {\"ar\": \"منشآت\", \"en\": \"Monsha\'at\"}}], \"title\": {\"ar\": \"شركاؤنا\", \"en\": \"Our Partners\"}}, \"type\": \"partners\"}]',1,'TGA-2025-IP-001','https://tga.gov.sa/certificate/innovation-platform','2026-02-15 20:12:22','2026-02-15 20:42:56'),(2,'Naql Thon 5','{\"hero\": {\"ar\": \"نقل ثون 5 - ابتكر مستقبل النقل السعودي\", \"en\": \"Naql Thon 5 - Innovate the Future of Saudi Transportation\"}, \"stats\": {\"prizes\": \"SAR 500,000\", \"tracks\": \"4\", \"mentors\": \"20+\", \"participants\": \"500+\"}, \"subtitle\": {\"ar\": \"48 ساعة لتحويل طريقة تنقل المملكة\", \"en\": \"48 Hours to Transform How Saudi Arabia Moves\"}}',1,'TGA-2026-NT5','https://tga.gov.sa/certificates/naqlthon5','2026-02-16 19:15:32','2026-02-16 19:15:32');
