INSERT INTO `pages` VALUES (1,'about-us','{\"ar\": \"من نحن\", \"en\": \"About Us\"}','{\"ar\": \"<p>منصة الابتكار هي نظام شامل لإدارة الهاكاثونات والابتكارات.</p>\", \"en\": \"<p>Innovation Platform is a comprehensive hackathon and innovation management system.</p>\"}',1,'2026-02-15 20:12:22','2026-02-15 20:12:22'),(2,'privacy-policy','{\"ar\": \"سياسة الخصوصية\", \"en\": \"Privacy Policy\"}','{\"ar\": \"<p>خصوصيتك مهمة لنا. نحن نجمع فقط البيانات اللازمة لتقديم خدماتنا.</p>\", \"en\": \"<p>Your privacy is important to us. We collect only necessary data to provide our services.</p>\"}',1,'2026-02-15 20:12:22','2026-02-15 20:12:22'),(3,'terms-and-conditions','{\"ar\": \"الشروط والأحكام\", \"en\": \"Terms & Conditions\"}','{\"ar\": \"<p>باستخدامك لهذه المنصة، فإنك توافق على هذه الشروط.</p>\", \"en\": \"<p>By using this platform, you agree to these terms.</p>\"}',1,'2026-02-15 20:12:22','2026-02-15 20:12:22'),(4,'naqlthon5-about','{\"ar\": \"عن نقل ثون 5\", \"en\": \"About Naql Thon 5\"}','{\"ar\": \"نقل ثون 5 هو النسخة الخامسة من هاكاثون النقل الرائد.\", \"en\": \"Naql Thon 5 is the fifth edition of Saudi Arabia\'s premier transportation hackathon.\"}',1,'2026-02-16 19:15:32','2026-02-16 19:15:32'),(5,'naqlthon5-prizes','{\"ar\": \"الجوائز\", \"en\": \"Prizes & Awards\"}','{\"ar\": \"مجموع الجوائز 500,000 ريال.\", \"en\": \"Total prize pool: SAR 500,000. Grand Prize: SAR 200,000.\"}',1,'2026-02-16 19:15:32','2026-02-16 19:15:32'),(6,'naqlthon5-faq','{\"ar\": \"الأسئلة الشائعة\", \"en\": \"FAQ\"}','{\"ar\": \"أسئلة شائعة حول نقل ثون 5.\", \"en\": \"Common questions about Naql Thon 5.\"}',1,'2026-02-16 19:15:32','2026-02-16 19:15:32');
