INSERT INTO `services` VALUES (1,'{\"ar\": \"خدمة البيئة التنظيمية التجريبية\", \"en\": \"Regulatory Sandbox Service\"}','{\"ar\": {\"tags\": \"بيئة تجريبية، ابتكار، تنظيم، تقنية النقل، بيئة اختبار\", \"email\": \"sandbox@tga.gov.sa\", \"phone\": \"+966-11-000-0000\", \"FAQsLink\": \"/ar/faqs\", \"mobileApp\": \"\", \"userManual\": \"/uploads/sandbox-user-manual-ar.pdf\", \"description\": \"البيئة التنظيمية التجريبية هي بيئة اختبار خاضعة للرقابة حيث يمكن لشركات النقل المبتكرة تجربة التقنيات والخدمات ونماذج الأعمال الجديدة تحت إشراف تنظيمي من الهيئة العامة للنقل. تتيح لك هذه الخدمة العمل بإعفاءات تنظيمية مؤقتة مع إثبات جدوى وسلامة ابتكارك.\", \"serviceCost\": \"مجاني\", \"targetAudience\": \"شركات تقنية النقل والشركات الناشئة والمبتكرون الذين يسعون لاختبار نماذج أعمال جديدة في بيئة منظمة\", \"paymentChannels\": \"لا ينطبق\", \"serviceChannels\": \"البوابة الإلكترونية، البريد الإلكتروني، الهاتف\", \"serviceDuration\": \"مراجعة الطلب: 30 يوم | تقييم الجاهزية: 15 يوم | فترة الاختبار: سنة تقويمية واحدة | التخرج: 30 يوم\", \"serviceLevelLink\": \"/ar/service-level-agreement\", \"startServiceLink\": \"/ar/programs\"}, \"en\": {\"tags\": \"Sandbox, Innovation, Regulation, Transport Technology, Testing Environment\", \"email\": \"sandbox@tga.gov.sa\", \"phone\": \"+966-11-000-0000\", \"FAQsLink\": \"/en/faqs\", \"mobileApp\": \"\", \"userManual\": \"/uploads/sandbox-user-manual-en.pdf\", \"description\": \"The Regulatory Sandbox is a controlled testing environment where innovative transport companies can trial new technologies, services, and business models under TGA regulatory supervision. This service allows you to operate with temporary regulatory exemptions while demonstrating the viability and safety of your innovation.\", \"serviceCost\": \"Free of charge\", \"targetAudience\": \"Transport technology companies, startups, and innovators seeking to test new business models in a regulated environment\", \"paymentChannels\": \"N/A\", \"serviceChannels\": \"Online Portal, Email, Phone\", \"serviceDuration\": \"Application review: 30 days | Readiness assessment: 15 days | Testing period: 1 calendar year | Graduation: 30 days\", \"serviceLevelLink\": \"/en/service-level-agreement\", \"startServiceLink\": \"/en/programs\"}}','{\"ar\": {\"steps\": \"<ol><li>سجّل في منصة الابتكار وأنشئ ملف شركتك.</li><li>اختر برنامج البيئة التنظيمية التجريبية وأكمل نموذج التقديم.</li><li>ارفع جميع المستندات المطلوبة بما في ذلك السجل التجاري والملخصات المالية والخطط التشغيلية.</li><li>قدم طلبك لمراجعة الهيئة العامة للنقل.</li><li>استلم نتائج تقييم الجاهزية خلال 15 يوم عمل.</li><li>عند الموافقة، ابدأ فترة الاختبار لمدة سنة واحدة تحت الإشراف التنظيمي.</li><li>قدم تقارير الامتثال الشهرية وتحديثات المشروع.</li><li>تخرج من البيئة التجريبية بترخيص تشغيل كامل.</li></ol>\", \"conditions\": \"<ul><li>يجب أن يكون المتقدم كيانًا مسجلًا قانونيًا في المملكة العربية السعودية.</li><li>يجب أن يكون الابتكار المقترح متعلقًا بقطاع النقل.</li><li>يجب على المتقدم إثبات الجدوى المالية والقدرة التشغيلية.</li><li>يجب أن تتوافق جميع الاختبارات مع معايير السلامة ومتطلبات حماية المستهلك.</li><li>يجب تقديم تقارير شهرية خلال فترة الاختبار.</li><li>يوافق المتقدم على التفتيش والمراقبة من قبل الهيئة في جميع الأوقات.</li></ul>\", \"requiredDocuments\": \"<ul><li>سجل تجاري ساري المفعول (مرتبط بالتحقق عبر واثق)</li><li>نسخة من عقد التأسيس ساري المفعول</li><li>خطة تشغيلية (السوق المستهدف، المناطق الجغرافية، توقعات الأرباح/الأجور)</li><li>خطة الخروج مع التحديات والمخاطر وعوامل النجاح</li><li>وثيقة تفاصيل التقنية</li><li>ملخص المخاطر لمستخدمي النقل مع خطة التخفيف</li><li>ملخص مالي (الأرباح والخسائر لآخر 3 سنوات، توقعات 3 سنوات، القوائم المالية المدققة، التمويل الحالي)</li><li>وثيقة سياسة التسعير</li><li>سياسة حماية المستفيدين</li></ul>\"}, \"en\": {\"steps\": \"<ol><li>Register on the Innovation Platform and create your company profile.</li><li>Select the Regulatory Sandbox program and complete the application form.</li><li>Upload all required documents including commercial registration, financial summaries, and operational plans.</li><li>Submit your application for review by TGA.</li><li>Receive readiness assessment results within 15 business days.</li><li>Upon approval, begin your 1-year testing period under regulatory supervision.</li><li>Submit monthly compliance reports and project updates.</li><li>Graduate from the sandbox with a full operating license.</li></ol>\", \"conditions\": \"<ul><li>The applicant must be a legally registered entity in the Kingdom of Saudi Arabia.</li><li>The proposed innovation must be related to the transport sector.</li><li>The applicant must demonstrate financial viability and operational capacity.</li><li>All testing must comply with safety standards and consumer protection requirements.</li><li>Monthly reports must be submitted during the testing period.</li><li>The applicant agrees to TGA inspection and monitoring at all times.</li></ul>\", \"requiredDocuments\": \"<ul><li>Valid Commercial Registration (linked with Wathiq verification)</li><li>Valid Incorporation Contract Copy</li><li>Operational Plan (target market, geographic areas, profit/wage expectations)</li><li>Exit Plan with challenges, risks, and success factors</li><li>Technology Details Document</li><li>Risk Summary for transport users with mitigation plan</li><li>Financial Summary (P&L past 3 years, projected P&L 3 years, audited financials, current funding)</li><li>Pricing Policy Document</li><li>Beneficiary Protection Policy</li></ul>\"}}','{\"ar\": {\"list\": [], \"title\": \"خدمات ذات صلة\", \"description\": \"استكشف الخدمات الأخرى التي تقدمها منصة الابتكار\"}, \"en\": {\"list\": [], \"title\": \"Related Services\", \"description\": \"Explore other services offered by the Innovation Platform\"}}',1,1,'2026-02-15 20:12:22','2026-02-15 20:42:56'),(2,'{\"ar\": \"الامتثال التنظيمي لتأجير السيارات\", \"en\": \"Car Rental Compliance & Regulatory Assessment\"}','{\"ar\": {\"tags\": \"امتثال، تأجير سيارات، معايير المركبات، حماية العملاء، تقييم تنظيمي\", \"email\": \"compliance@tga.gov.sa\", \"phone\": \"+966-11-000-0000\", \"FAQsLink\": \"/ar/faqs\", \"mobileApp\": \"\", \"userManual\": \"/uploads/compliance-manual-ar.pdf\", \"description\": \"خدمة تقييم الامتثال الشاملة لمشغلي تأجير السيارات لضمان الالتزام بالمبادئ التوجيهية التنظيمية للهيئة العامة للنقل. تقيّم هذه الخدمة متطلبات المنشأة ومعايير المركبات وإجراءات حماية العملاء من خلال التقارير المنظمة والتفتيشات الدورية.\", \"serviceCost\": \"مشمول في رسوم ترخيص المشغل\", \"targetAudience\": \"مشغلو تأجير السيارات المرخصون في المملكة العربية السعودية\", \"paymentChannels\": \"سداد، تحويل بنكي\", \"serviceChannels\": \"البوابة الإلكترونية، التفتيش الميداني\", \"serviceDuration\": \"تقارير امتثال شهرية | تفتيشات ميدانية ربع سنوية\", \"serviceLevelLink\": \"/ar/service-level-agreement\", \"startServiceLink\": \"/ar/programs\"}, \"en\": {\"tags\": \"Compliance, Car Rental, Vehicle Standards, Customer Protection, Regulatory Assessment\", \"email\": \"compliance@tga.gov.sa\", \"phone\": \"+966-11-000-0000\", \"FAQsLink\": \"/en/faqs\", \"mobileApp\": \"\", \"userManual\": \"/uploads/compliance-manual-en.pdf\", \"description\": \"A comprehensive compliance assessment service for car rental operators to ensure adherence to TGA regulatory guidelines. This service evaluates establishment requirements, vehicle standards, and customer protection measures through structured reporting and periodic inspections.\", \"serviceCost\": \"Included in operator licensing fees\", \"targetAudience\": \"Licensed car rental operators in the Kingdom of Saudi Arabia\", \"paymentChannels\": \"SADAD, Bank Transfer\", \"serviceChannels\": \"Online Portal, Field Inspection\", \"serviceDuration\": \"Monthly compliance reports | Quarterly on-site inspections\", \"serviceLevelLink\": \"/en/service-level-agreement\", \"startServiceLink\": \"/en/programs\"}}','{\"ar\": {\"steps\": \"<ol><li>سجل الدخول إلى منصة الابتكار ببيانات اعتماد المشغل.</li><li>انتقل إلى قسم الامتثال لتأجير السيارات.</li><li>أكمل نماذج تقارير الامتثال الشهرية التي تغطي متطلبات المنشأة والمركبات والعملاء.</li><li>ارفع الوثائق الداعمة وأدلة الامتثال.</li><li>قدم تقريرك لمراجعة الهيئة العامة للنقل.</li><li>استلم نتائج تقييم الامتثال وأي متطلبات إجراءات تصحيحية.</li></ol>\", \"conditions\": \"<ul><li>يجب تقديم التقارير شهريًا بحلول الخامس عشر من كل شهر.</li><li>يجب أن تحافظ جميع المركبات على شهادات تسجيل وفحص سارية.</li><li>يجب على المشغلين الحفاظ على تغطية تأمينية شاملة.</li><li>يجب حل شكاوى العملاء ضمن الأطر الزمنية المحددة.</li><li>يجب أن يكون تتبع GPS نشطًا على جميع مركبات التأجير.</li></ul>\", \"requiredDocuments\": \"<ul><li>رخصة مشغل سارية المفعول</li><li>وثائق تسجيل أسطول المركبات</li><li>شهادات التأمين لجميع المركبات</li><li>سجل شكاوى العملاء</li><li>سجلات فحص المركبات</li><li>وثائق نظام تتبع GPS</li><li>سجلات تدريب الموظفين</li></ul>\"}, \"en\": {\"steps\": \"<ol><li>Log in to the Innovation Platform with your operator credentials.</li><li>Navigate to the Car Rental Compliance section.</li><li>Complete the monthly compliance report forms covering establishment, vehicle, and customer requirements.</li><li>Upload supporting documentation and evidence of compliance.</li><li>Submit your report for TGA review.</li><li>Receive compliance assessment results and any corrective action requirements.</li></ol>\", \"conditions\": \"<ul><li>Reports must be submitted monthly by the 15th of each month.</li><li>All vehicles must maintain valid registration and inspection certificates.</li><li>Operators must maintain comprehensive insurance coverage.</li><li>Customer complaints must be resolved within the specified timeframes.</li><li>GPS tracking must be active on all rental vehicles.</li></ul>\", \"requiredDocuments\": \"<ul><li>Valid operator license</li><li>Vehicle fleet registration documents</li><li>Insurance certificates for all vehicles</li><li>Customer complaint log</li><li>Vehicle inspection records</li><li>GPS tracking system documentation</li><li>Employee training records</li></ul>\"}}','{\"ar\": {\"list\": [], \"title\": \"خدمات ذات صلة\", \"description\": \"خدمات أخرى لمشغلي النقل\"}, \"en\": {\"list\": [], \"title\": \"Related Services\", \"description\": \"Other services for transport operators\"}}',1,2,'2026-02-15 20:12:22','2026-02-15 20:42:56'),(3,'{\"ar\": \"التسجيل وتشكيل الفرق\", \"en\": \"Hackathon Registration & Team Formation\"}','{\"category\": \"hackathon\"}','{\"ar\": \"سجل وشكّل فريقك مع المطابقة الذكية.\", \"en\": \"Register and form your dream team with smart matching.\"}','[]',1,3,'2026-02-16 19:15:32','2026-02-16 19:15:32'),(4,'{\"ar\": \"الإرشاد والتوجيه\", \"en\": \"Mentorship & Expert Guidance\"}','{\"category\": \"hackathon\"}','{\"ar\": \"تواصل مع مرشدين رائدين.\", \"en\": \"Connect with industry-leading mentors.\"}','[]',1,4,'2026-02-16 19:15:32','2026-02-16 19:15:32'),(5,'{\"ar\": \"تقييم المشاريع والتحكيم\", \"en\": \"Project Evaluation & Judging\"}','{\"category\": \"hackathon\"}','{\"ar\": \"تقييم بالذكاء الاصطناعي مع تحكيم خبير.\", \"en\": \"AI-powered evaluation combined with expert judging.\"}','[]',1,5,'2026-02-16 19:15:32','2026-02-16 19:15:32');
