INSERT INTO `task_templates` VALUES (1,3,NULL,'{\"ar\": \"تقديم نموذج العمل التجاري\", \"en\": \"Business Model Canvas Submission\"}','{\"ar\": \"قدم نموذج العمل التجاري المكتمل لابتكارك في مجال النقل.\", \"en\": \"Submit a completed Business Model Canvas for your transportation innovation.\"}','{\"ar\": \"1. قم بتحميل قالب نموذج العمل التجاري\\n2. املأ جميع الأقسام التسعة\\n3. ارفع كملف PDF أو DOCX\\n4. أرفق التوقعات المالية الداعمة\", \"en\": \"1. Download the Business Model Canvas template\\n2. Fill in all 9 sections\\n3. Upload as PDF or DOCX\\n4. Include supporting financial projections\"}','medium',8,'Business Planning',1,166,0,'2026-02-16 16:53:11','2026-02-16 16:53:11'),(2,3,NULL,'{\"ar\": \"قائمة التحقق من الامتثال التنظيمي\", \"en\": \"Regulatory Compliance Checklist\"}','{\"ar\": \"أكمل قائمة التقييم الذاتي للامتثال التنظيمي لهيئة النقل العام.\", \"en\": \"Complete the TGA regulatory compliance self-assessment checklist.\"}','{\"ar\": \"1. راجع الإطار التنظيمي للصندوق الرملي لهيئة النقل\\n2. أكمل كل عنصر امتثال\\n3. أرفق الأدلة الداعمة لكل متطلب\\n4. قدم مع بيان امتثال موقع من فريقك القانوني\", \"en\": \"1. Review TGA sandbox regulatory framework\\n2. Complete each compliance item\\n3. Attach supporting evidence for each requirement\\n4. Submit with a compliance statement signed by your legal team\"}','hard',16,'Compliance',1,166,0,'2026-02-16 16:53:11','2026-02-16 16:53:11'),(3,3,NULL,'{\"ar\": \"تقرير مؤشرات الأداء الشهري\", \"en\": \"Monthly KPI Report\"}','{\"ar\": \"قدم تقرير مؤشرات الأداء الرئيسية الشهري.\", \"en\": \"Submit monthly key performance indicators report.\"}','{\"ar\": \"1. اجمع المقاييس التشغيلية من أنظمتك\\n2. املأ قالب مؤشرات الأداء بالأرقام الفعلية\\n3. أضف تحليلاً لأي انحراف عن الأهداف\\n4. أضف خطط عمل للمجالات ذات الأداء المنخفض\", \"en\": \"1. Collect operational metrics from your systems\\n2. Fill the KPI template with actual numbers\\n3. Include analysis for any deviation from targets\\n4. Add action plans for underperforming areas\"}','easy',4,'Reporting',1,166,0,'2026-02-16 16:53:11','2026-02-16 16:53:11'),(4,3,NULL,'{\"ar\": \"تقييم السلامة والمخاطر\", \"en\": \"Safety & Risk Assessment\"}','{\"ar\": \"أجرِ وقدم تقييمًا شاملاً للسلامة والمخاطر لعملياتك.\", \"en\": \"Conduct and submit a comprehensive safety and risk assessment for your operations.\"}','{\"ar\": \"1. حدد جميع المخاطر التشغيلية\\n2. صنف كل خطر حسب الاحتمالية والتأثير\\n3. وثق استراتيجيات التخفيف\\n4. أرفق إجراءات الاستجابة للحوادث\", \"en\": \"1. Identify all operational risks\\n2. Rate each risk by likelihood and impact\\n3. Document mitigation strategies\\n4. Include incident response procedures\"}','hard',12,'Safety',1,166,0,'2026-02-16 16:53:11','2026-02-16 16:53:11'),(5,3,NULL,'{\"ar\": \"تحليل ملاحظات العملاء\", \"en\": \"Customer Feedback Analysis\"}','{\"ar\": \"حلل بيانات ملاحظات العملاء وقدم توصيات للتحسين.\", \"en\": \"Analyze customer feedback data and submit improvement recommendations.\"}','{\"ar\": \"1. صدّر ملاحظات العملاء من نظامك\\n2. صنف الملاحظات حسب الموضوع\\n3. حدد أهم 5 مجالات للتحسين\\n4. اقترح بنود عمل مع جداول زمنية\", \"en\": \"1. Export customer feedback from your system\\n2. Categorize feedback by theme\\n3. Identify top 5 improvement areas\\n4. Propose action items with timelines\"}','medium',6,'Customer Experience',1,166,0,'2026-02-16 16:53:11','2026-02-16 16:53:11'),(6,5,NULL,'{\"ar\": \"تحديد بيان المشكلة\", \"en\": \"Define Problem Statement\"}','{\"ar\": \"حدد مشكلة النقل وشخصيات المستخدمين.\", \"en\": \"Define the transportation problem and user personas.\"}','{\"ar\": \"اتبع إرشادات الهاكاثون.\", \"en\": \"Follow hackathon guidelines.\"}','easy',3,'Ideation',1,166,0,'2026-02-11 19:15:32','2026-02-16 19:15:32'),(7,5,NULL,'{\"ar\": \"وثيقة البنية التقنية\", \"en\": \"Technical Architecture Doc\"}','{\"ar\": \"أنشئ مخطط البنية التقنية.\", \"en\": \"Create technical architecture diagram.\"}','{\"ar\": \"اتبع إرشادات الهاكاثون.\", \"en\": \"Follow hackathon guidelines.\"}','medium',5,'Technical',1,166,0,'2026-02-11 19:15:32','2026-02-16 19:15:32'),(8,5,NULL,'{\"ar\": \"بناء النموذج الأولي\", \"en\": \"Build MVP Prototype\"}','{\"ar\": \"طور نموذجاً أولياً.\", \"en\": \"Develop minimum viable prototype.\"}','{\"ar\": \"اتبع إرشادات الهاكاثون.\", \"en\": \"Follow hackathon guidelines.\"}','hard',16,'Development',1,166,0,'2026-02-11 19:15:32','2026-02-16 19:15:32'),(9,5,NULL,'{\"ar\": \"إعداد العرض التقديمي\", \"en\": \"Prepare Pitch Deck\"}','{\"ar\": \"أنشئ عرضاً من 10 شرائح.\", \"en\": \"Create 10-slide pitch deck.\"}','{\"ar\": \"اتبع إرشادات الهاكاثون.\", \"en\": \"Follow hackathon guidelines.\"}','medium',4,'Presentation',1,166,0,'2026-02-11 19:15:32','2026-02-16 19:15:32'),(10,5,NULL,'{\"ar\": \"تسجيل فيديو العرض\", \"en\": \"Record Demo Video\"}','{\"ar\": \"سجل فيديو عرض 3 دقائق.\", \"en\": \"Record 3-minute demo video.\"}','{\"ar\": \"اتبع إرشادات الهاكاثون.\", \"en\": \"Follow hackathon guidelines.\"}','easy',2,'Presentation',1,166,0,'2026-02-11 19:15:32','2026-02-16 19:15:32');
/*!40000 ALTER TABLE `task_templates` ENABLE KEYS */;
UNLOCK TABLES;

